/// <summary>
/// PaffH 20.07.22
/// </summary>
/// <param name = "_refRecId">RefRecId</param>
/// <returns>NDXProdIdentTechnique</returns>
public static NDXProdIdentTechnique findRecId(RefRecId _refRecId)
{
    NDXProdIdentTechnique nDXProdIdentTechnique;
    select firstonly nDXProdIdentTechnique where nDXProdIdentTechnique.RecId == _refRecId;
    return nDXProdIdentTechnique;
}

/// <summary>
/// PaffH 08.08.22
/// </summary>
/// <param name = "_id">NDXProdIdentTechniqueId</param>
/// <param name = "_forUpdate">boolean</param>
/// <returns>NDXProdIdentTechnique</returns>
public static NDXProdIdentTechnique find(NDXProdIdentTechniqueId _id, boolean _forUpdate = true)
{
    NDXProdIdentTechnique nDXProdIdentTechnique;
    nDXProdIdentTechnique.selectForUpdate(_forUpdate);
    select firstonly nDXProdIdentTechnique
        where nDXProdIdentTechnique.ID == _id;

    return nDXProdIdentTechnique;
}

/// <summary>
/// PaffH 08.08.22
/// </summary>
/// <param name = "_id">NDXProdIdentTechniqueId</param>
/// <param name = "_doInsert">boolean</param>
/// <returns>NDXProdIdentTechnique</returns>
public static NDXProdIdentTechnique findOrCreate(NDXProdIdentTechniqueId _id, boolean _doInsert = true)
{
    NDXProdIdentTechnique nDXProdIdentTechnique;

    nDXProdIdentTechnique = NDXProdIdentTechnique::find(_id, true);
    if (!nDXProdIdentTechnique)
    {
        nDXProdIdentTechnique.ID = _id;
        if (_doInsert)
        {
            nDXProdIdentTechnique.insert();
        }
    }
    return nDXProdIdentTechnique;
}
